//! Kbd: a keyboard shortcut as keycaps, one cap per key ("⌘", "⇧", "K").
//!
//!   root (row; gap by size)
//!   +-- cap (text: the key; min width = height, raised bottom edge) per key
//!
//! - `keys`: the caps in order (a source: the row follows it, e.g. while recording a shortcut);
//! - `size`: `.sm` (20 pt caps, the default) / `.md` (24 pt);
//! - `tone`: `.neutral` / `.accent` (recording) / `.warning` (conflict) / `.danger` (invalid),
//!   Tag's tonal colors; a source.
//!
//! Yix: `<W.Kbd keys={caps(vm)} tone={tone(vm)} />`. Zig: `W.Kbd(.{ .keys = &.{ "⌘", "K" } })`.
//! The caps carry no semantics of their own; give the row a label through `a11y` when the
//! glyphs do not read well ("Command Shift K").
//!
//! Hand-written Zig over a `.yss` recipe (like Pressable): it stays out of the LP3 template
//! equivalence fixtures, whose goldens are regenerated by a separate reviewed step.
const std = @import("std");
const core = @import("../../core.zig");
const v = @import("../../view.zig");
const reactive = @import("../../reactive.zig");
const Scope = reactive.Scope;
const Source = reactive.Source;
const Cx = core.Cx;
const Node = core.Node;
const S = @import("_styles.yss.zig");

pub const KbdSize = enum { sm, md };
pub const KbdTone = enum { neutral, accent, warning, danger };

pub const KbdProps = struct {
    keys: Source([]const []const u8) = .{ .value = &.{} },
    /// Cap size (structural: read when the row is built).
    size: KbdSize = .sm,
    tone: Source(KbdTone) = .{ .value = .neutral },
};

/// `W.Kbd(.{ .keys = &.{ "⌘", "⇧", "K" }, .tone = tone })`.
pub fn Kbd(args: anytype) v.ComponentOf(mountKbd) {
    return v.component(mountKbd, reactive.props.coerce(KbdProps, args));
}

const Cap = struct {
    size: KbdSize,
    tone: Source(KbdTone),
};

fn keyOf(key: []const u8) u64 {
    return std.hash.Wyhash.hash(0x6b6264, key);
}

fn cap(c: Cap, key: []const u8, scope: *Scope, cx: *Cx) anyerror!*Node {
    return v.render(scope, cx, v.text(.{
        .box = S.KbdCap.of(.{ .size = c.size, .tone = c.tone }),
        .style = S.KbdLabel.of(.{ .size = c.size, .tone = c.tone }),
    }, key));
}

fn mountKbd(props: KbdProps, scope: *Scope, cx: *Cx) anyerror!*Node {
    const root = try v.render(scope, cx, v.row(.{
        .style = .{ S.row, S.KbdRow.of(.{ .size = props.size }) },
    }, v.eachWith(Cap{ .size = props.size, .tone = props.tone }, props.keys, keyOf, cap)));
    root.meta.ownership.meta.component_name = "Kbd";
    return root;
}

// ===== Tests =====

const testing = std.testing;
const theme = core.theme;

/// The caps (a dynamic list keeps its own anchor nodes beside them).
fn caps(row: *Node, out: []*Node) []*Node {
    var n: usize = 0;
    for (row.children.items) |c| if (c.getText() != null) {
        out[n] = c;
        n += 1;
    };
    return out[0..n];
}

fn render(scope: *Scope, cx: *Cx, element: anytype) !*Node {
    const root = try v.render(scope, cx, element);
    cx.root = root;
    cx.layout();
    return root;
}

test "Kbd: one cap per key, equal minimum width, raised bottom edge" {
    const cx = try Cx.init(testing.allocator, testing.io);
    defer cx.deinit();
    cx.setTheme(&theme.light);
    const scope = try Scope.init(testing.allocator, null, cx.owner);
    defer scope.dispose();
    const root = try render(scope, cx, v.col(.{}, .{Kbd(.{ .keys = &.{ "⌘", "K", "Space" } })}));
    const row = root.children.items[0];
    try testing.expectEqualStrings("Kbd", row.meta.ownership.meta.component_name.?);
    var buf: [8]*Node = undefined;
    const cs = caps(row, &buf);
    try testing.expectEqual(@as(usize, 3), cs.len);
    const k = cs[1];
    try testing.expectEqualStrings("K", k.getText().?.content);
    const r = k.rectFromWorldOrFallback();
    try testing.expectApproxEqAbs(@as(f32, 20), r.h, 0.01);
    try testing.expect(r.w >= 20 - 0.01);
    try testing.expect(cs[2].rectFromWorldOrFallback().w > r.w);
    try testing.expectEqual(@as(f32, 2), k.style.border.side_widths[core.Border.SIDE_BOTTOM]);
    try testing.expectEqual(theme.light.tokens.color.bg_primary, k.getBackground());
}

test "Kbd: keys and tone follow their sources; md caps are 24 pt" {
    const cx = try Cx.init(testing.allocator, testing.io);
    defer cx.deinit();
    cx.setTheme(&theme.light);
    const scope = try Scope.init(testing.allocator, null, cx.owner);
    defer scope.dispose();
    const keys = try scope.createSignal([]const []const u8, &.{ "⌘", "K" });
    const tone = try scope.createSignal(KbdTone, .neutral);
    const root = try render(scope, cx, v.col(.{}, .{Kbd(.{ .keys = keys, .tone = tone, .size = .md })}));
    const row = root.children.items[0];
    var buf: [8]*Node = undefined;
    try testing.expectEqual(@as(usize, 2), caps(row, &buf).len);
    try testing.expectApproxEqAbs(@as(f32, 24), caps(row, &buf)[0].rectFromWorldOrFallback().h, 0.01);
    keys.set(&.{ "⌘", "⇧", "P" });
    cx.layout();
    try testing.expectEqual(@as(usize, 3), caps(row, &buf).len);
    try testing.expectEqualStrings("P", caps(row, &buf)[2].getText().?.content);
    tone.set(.danger);
    try testing.expectEqual(theme.light.tokens.color.danger_tag_bg, caps(row, &buf)[0].getBackground());
    try testing.expectEqual(theme.light.tokens.color.danger, caps(row, &buf)[0].getText().?.color);
    keys.set(&.{});
    try testing.expectEqual(@as(usize, 0), caps(row, &buf).len);
}

test "Kbd: theme switch repaints the caps" {
    const cx = try Cx.init(testing.allocator, testing.io);
    defer cx.deinit();
    cx.setTheme(&theme.light);
    const scope = try Scope.init(testing.allocator, null, cx.owner);
    defer scope.dispose();
    const root = try render(scope, cx, v.col(.{}, .{Kbd(.{ .keys = &.{"Esc"} })}));
    var buf: [8]*Node = undefined;
    const k = caps(root.children.items[0], &buf)[0];
    try testing.expectEqual(theme.light.tokens.color.bg_primary, k.getBackground());
    cx.setTheme(&theme.dark);
    try testing.expectEqual(theme.dark.tokens.color.bg_primary, k.getBackground());
}
